TEST_F(BeatThisWorkerTest, SuccessiveAnalyzerInstancesReuseTheLoadedWorker) {
    const auto first = runWorkerJob(options());
    const auto second = runWorkerJob(options());
    expectSuccessful(first);
    expectSuccessful(second);
    EXPECT_GT(pid(first), 0);
    EXPECT_EQ(pid(first), pid(second));
    EXPECT_FALSE(first.diagnostics.value("worker_reused").toBool());
    EXPECT_TRUE(second.diagnostics.value("worker_reused").toBool());
    EXPECT_EQ(1, starts());
    EXPECT_EQ(first.beats, second.beats);
    EXPECT_EQ(123456, second.diagnostics.value("worker_peak_rss_bytes").toInt());
    ASSERT_TRUE(second.timings.contains("inference"));
    EXPECT_DOUBLE_EQ(3, second.timings.value("inference").toDouble());
    expectTemporaryAudioRemoved();
}

TEST_F(BeatThisWorkerTest, RecoverableJobFailureDoesNotExposePreviousResults) {
    const auto first = runWorkerJob(options());
    expectSuccessful(first);
    setMode("job_error");
    const auto failed = runWorkerJob(options());
    EXPECT_FALSE(failed.finalized);
    EXPECT_TRUE(failed.beats.isEmpty());
    EXPECT_TRUE(failed.downbeats.isEmpty());
    setMode("normal");
    const auto next = runWorkerJob(options());
    expectSuccessful(next);
    EXPECT_EQ(pid(first), pid(next));
    EXPECT_EQ(1, starts());
    expectTemporaryAudioRemoved();
}

