TEST_F(BeatThisPersistentModelTest, OneShotAndWarmWorkersPreservePositionsAcrossSampleRates) {
    const auto python = qEnvironmentVariable("MIXXX_TEST_BEAT_THIS_PYTHON");
    const auto model = qEnvironmentVariable("MIXXX_TEST_BEAT_THIS_MODEL");
    if (python.isEmpty() || model.isEmpty()) {
        GTEST_SKIP() << "Set MIXXX_TEST_BEAT_THIS_PYTHON and "
                        "MIXXX_TEST_BEAT_THIS_MODEL for real-model validation";
    }
    BeatDetectionSettings settings(config());
    settings.setBeatThisModel(model);
    const auto script =
            QDir(config()->getResourcePath())
                    .filePath(QStringLiteral("analysis/beat_this_worker.py"));
    const AnalyzerBeatThis::Options persistentOptions{
            python, script, model, settings.getBeatThisModelSha256()};
    auto oneShotOptions = persistentOptions;
    oneShotOptions.persistent = false;
    qint64 firstPid = 0;
    for (const int sampleRate : {22050, 48000, 44100}) {
        SCOPED_TRACE(sampleRate);
        const auto rate = mixxx::audio::SampleRate(sampleRate);
        constexpr int kSeconds = 24;
        std::vector<CSAMPLE> samples(kSeconds * sampleRate * 2, 0.0f);
        for (int beat = 0; beat < kSeconds * 2; ++beat) {
            const int first = static_cast<int>(std::lround((0.1 + beat * 0.5) * sampleRate));
            for (int frame = 0; frame < sampleRate / 8 &&
                    first + frame < kSeconds * sampleRate;
                    ++frame) {
                const double time = frame / static_cast<double>(sampleRate);
                const auto pulse = static_cast<CSAMPLE>((beat % 4 == 0 ? 0.9 : 0.6) *
                        std::exp(-80 * time) * std::cos(2 * M_PI * 80 * time));
                samples[2 * (first + frame)] = samples[2 * (first + frame) + 1] = pulse;
            }
        }
        AnalyzerBeatThis oneShot(oneShotOptions);
        AnalyzerBeatThis persistent(persistentOptions);
        ASSERT_TRUE(oneShot.initialize(rate));
        ASSERT_TRUE(persistent.initialize(rate));
        for (size_t first = 0; first < samples.size(); first += 8192) {
            const auto count = static_cast<SINT>(std::min(size_t(8192), samples.size() - first));
            ASSERT_TRUE(oneShot.processSamples(samples.data() + first, count));
            ASSERT_TRUE(persistent.processSamples(samples.data() + first, count));
        }
        QElapsedTimer timer;
        timer.start();
        ASSERT_TRUE(oneShot.finalize());
        const double oneShotMs = timer.nsecsElapsed() / 1e6;
        timer.restart();
        ASSERT_TRUE(persistent.finalize());
        const double persistentMs = timer.nsecsElapsed() / 1e6;
        EXPECT_EQ(oneShot.getBeats(), persistent.getBeats());
        EXPECT_EQ(oneShot.getDownbeats(), persistent.getDownbeats());
        const auto diagnostics = persistent.analysisDiagnostics();
        const auto currentPid = static_cast<qint64>(diagnostics.value("worker_pid").toDouble());
        EXPECT_GT(currentPid, 0);
        EXPECT_EQ(firstPid != 0, diagnostics.value("worker_reused").toBool());
        if (firstPid == 0) {
            firstPid = currentPid;
        } else {
            EXPECT_EQ(firstPid, currentPid);
        }
        const QJsonObject report{{"sample_rate", sampleRate},
                {"one_shot_finalize_ms", oneShotMs},
                {"persistent_finalize_ms", persistentMs},
                {"one_shot_timings_ms", oneShot.timingMetrics()},
                {"persistent_timings_ms", persistent.timingMetrics()},
                {"persistent_diagnostics", diagnostics}};
        std::cout << QJsonDocument(report).toJson(QJsonDocument::Compact).constData() << std::endl;
    }
}

